-- School Support Plan (doc under the Website Governance Plan Playbook), for Charlene A. Collins
-- and the District Web Team (V, 2026-10-27). Phase 1 support, the 2026-27 PIVOT memo, the
-- October 7 leadership asks, Phase 2 (proposed), and next steps. Shell (head, styles, header)
-- reused from the October 7 meeting notes doc, built from template f7037d82. Recipients copy
-- the Playbook's list, plus Charlene A. Collins. Applied 2026-10-27 via the one-time function
-- ve-once-school-support-plan (now a 410 stub); Charlene added by execute_sql.

insert into public.briefings (tenant_id, brand_slug, type, slug, title, author, status, briefing_date, metadata, content)
select '00000000-0000-4000-a000-000000000001', 'bcps', 'record', 'bcps-school-support-plan', 'School Support Plan', 'logan', 'published', date '2026-10-27',
  jsonb_build_object('parent_playbook_slug', 'bcps-website-governance-plan-2026-06-10', 'doc_kind', 'plan', 'client', true,
    'template_id', 'f7037d82-c5e2-4997-8631-aa68993157a4', 'shell_from', 'bcps-website-governance-plan-2026-06-10-meeting-2026-10-07'),
  replace(split_part(s.content, '<main>', 1),
    '<title>Website Standards and Leadership Support: October 7, 2026</title>', '<title>School Support Plan</title>')
  || '<main>' || chr(10) || convert_from(decode('', 'base64'), 'UTF8') || chr(10) || '</main>' || chr(10) || '</body>' || chr(10) || '</html>'
from public.briefings s
where s.slug = 'bcps-website-governance-plan-2026-06-10-meeting-2026-10-07'
  and not exists (select 1 from public.briefings where slug = 'bcps-school-support-plan');

insert into public.bcps_brief_recipients (brief_slug, attendee_name, attendee_email, added_by)
select 'bcps-school-support-plan', r.attendee_name, r.attendee_email, 'auto'
from public.bcps_brief_recipients r
where r.brief_slug = 'bcps-website-governance-plan-2026-06-10'
  and not exists (select 1 from public.bcps_brief_recipients x
                  where x.brief_slug = 'bcps-school-support-plan' and lower(x.attendee_email) = lower(r.attendee_email));

insert into public.bcps_brief_recipients (brief_slug, attendee_name, attendee_email, added_by)
select 'bcps-school-support-plan', 'Charlene A. Collins', 'charlene.collins@browardschools.com', 'auto'
where not exists (select 1 from public.bcps_brief_recipients
                  where brief_slug = 'bcps-school-support-plan' and lower(attendee_email) = 'charlene.collins@browardschools.com');
